import type { Source } from "./Core";
/**
 * A function that has next, error and complete callbacks
 * and optionally returns a cleanup function.
 */
declare type Producer<T, E> = ((next: (data: T) => void, error: (reason: E) => void, complete: () => void) => (() => void) | void) | undefined;
/**
 * This function creates a new listenable
 * callbag given an optional producer
 * that emits to the sink passed in.
 * The producer function can optionally return a cleanup function
 * that is called if the stream is ended by the sink.
 * (A listenable callbag is one that emits data
 * without waiting for the sink to request data.)
 *
 * If a producer is not provided, no value will be emitted and
 * the stream will complete.
 *
 * If a producer is provided without any callbacks, nothing will
 * be emitted and the stream will never end.
 *
 * Adapted from https://github.com/franciscotln/callbag-create
 *
 * @template T The type of data being emitted.
 * @template E The type of error that may be emitted.
 * @param producer An optional function that has next, error
 *     and complete callbacks and optionally returns a cleanup function.
 *
 * @internal
 */
export declare const createListenable: <T, E = unknown>(producer?: Producer<T, E>) => Source<T, E>;
export {};
